#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    long long maxCoins(vector<int>& lane1, vector<int>& lane2) {
        int n = lane1.size();
        const long long INF = 1e18;
        long long ans = -INF;
        long long dp0 = -INF, dp1 = -INF, dp2 = -INF;

        for (int i = 0; i < n; i++) {
            long long c1 = lane1[i];
            long long c2 = lane2[i];

            long long new_dp0 = max(c1, dp0 == -INF ? -INF : dp0 + c1);
            long long new_dp1 = max({c2, dp0 == -INF ? -INF : dp0 + c2, dp1 == -INF ? -INF : dp1 + c2});
            long long new_dp2 = max(dp1 == -INF ? -INF : dp1 + c1, dp2 == -INF ? -INF : dp2 + c1);

            dp0 = new_dp0;
            dp1 = new_dp1;
            dp2 = new_dp2;

            ans = max({ans, dp0, dp1, dp2});
        }
        return ans;
    }
};

class Solution {
    public long maxCoins(int[] lane1, int[] lane2) {
        int n = lane1.length;
        final long INF = (long) 1e18;
        long ans = -INF;
        long dp0 = -INF, dp1 = -INF, dp2 = -INF;

        for (int i = 0; i < n; i++) {
            long c1 = lane1[i];
            long c2 = lane2[i];

            long new_dp0 = Math.max(c1, dp0 == -INF ? -INF : dp0 + c1);
            long new_dp1 = Math.max(c2, Math.max(dp0 == -INF ? -INF : dp0 + c2, dp1 == -INF ? -INF : dp1 + c2));
            long new_dp2 = Math.max(dp1 == -INF ? -INF : dp1 + c1, dp2 == -INF ? -INF : dp2 + c1);

            dp0 = new_dp0;
            dp1 = new_dp1;
            dp2 = new_dp2;

            ans = Math.max(ans, Math.max(dp0, Math.max(dp1, dp2)));
        }
        return ans;
    }
}

/**
 * @param {number[]} lane1
 * @param {number[]} lane2
 * @return {number}
 */
var maxCoins = function(lane1, lane2) {
    const n = lane1.length;
    let ans = -Infinity;
    let dp0 = -Infinity;
    let dp1 = -Infinity;
    let dp2 = -Infinity;

    for (let i = 0; i < n; i++) {
        const c1 = lane1[i];
        const c2 = lane2[i];

        const new_dp0 = Math.max(c1, dp0 + c1);
        const new_dp1 = Math.max(c2, dp0 + c2, dp1 + c2);
        const new_dp2 = Math.max(dp1 + c1, dp2 + c1);

        dp0 = new_dp0;
        dp1 = new_dp1;
        dp2 = new_dp2;

        ans = Math.max(ans, dp0, dp1, dp2);
    }
    return ans;
};
